DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[Product]([ProductID],[Name],[ProductNumber],[MakeFlag],[FinishedGoodsFlag],[Color],[SafetyStockLevel],[ReorderPoint],[StandardCost],[ListPrice],[Size],[SizeUnitMeasureCode],[WeightUnitMeasureCode],[Weight],[DaysToManufacture],[ProductLine],[Class],[Style],[ProductSubcategoryID],[ProductModelID],[SellStartDate],[SellEndDate],[DiscontinuedDate],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[Name],S.[ProductNumber],S.[MakeFlag],S.[FinishedGoodsFlag],S.[Color],S.[SafetyStockLevel],S.[ReorderPoint],S.[StandardCost],S.[ListPrice],S.[Size],S.[SizeUnitMeasureCode],S.[WeightUnitMeasureCode],S.[Weight],S.[DaysToManufacture],S.[ProductLine],S.[Class],S.[Style],S.[ProductSubcategoryID],S.[ProductModelID],S.[SellStartDate],S.[SellEndDate],S.[DiscontinuedDate],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_Product S;
INSERT stg.[Product]([ProductID],[Name],[ProductNumber],[MakeFlag],[FinishedGoodsFlag],[Color],[SafetyStockLevel],[ReorderPoint],[StandardCost],[ListPrice],[Size],[SizeUnitMeasureCode],[WeightUnitMeasureCode],[Weight],[DaysToManufacture],[ProductLine],[Class],[Style],[ProductSubcategoryID],[ProductModelID],[SellStartDate],[SellEndDate],[DiscontinuedDate],[rowguid],[ModifiedDate],LoadBatchID) SELECT [ProductID],[Name],[ProductNumber],[MakeFlag],[FinishedGoodsFlag],[Color],[SafetyStockLevel],[ReorderPoint],[StandardCost],[ListPrice],[Size],[SizeUnitMeasureCode],[WeightUnitMeasureCode],[Weight],[DaysToManufacture],[ProductLine],[Class],[Style],[ProductSubcategoryID],[ProductModelID],[SellStartDate],[SellEndDate],[DiscontinuedDate],[rowguid],[ModifiedDate],@B FROM etl_raw.[Product];
INSERT etl_v2.SourceChange SELECT @B,N'Production.Product','I',@Next,(SELECT R.[ProductID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[Product] R;
END ELSE BEGIN
SELECT [ProductID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_Product FROM ssis_flow.Delta_Product;
INSERT etl_v2.SourceChange SELECT @B,N'Production.Product',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[ProductID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_Product C LEFT JOIN etl_raw.[Product] R ON R.[ProductID]=C.[ProductID];
DELETE R FROM etl_raw.[Product] R JOIN #CT_Product C ON R.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[Name]=S.[Name],R.[ProductNumber]=S.[ProductNumber],R.[MakeFlag]=S.[MakeFlag],R.[FinishedGoodsFlag]=S.[FinishedGoodsFlag],R.[Color]=S.[Color],R.[SafetyStockLevel]=S.[SafetyStockLevel],R.[ReorderPoint]=S.[ReorderPoint],R.[StandardCost]=S.[StandardCost],R.[ListPrice]=S.[ListPrice],R.[Size]=S.[Size],R.[SizeUnitMeasureCode]=S.[SizeUnitMeasureCode],R.[WeightUnitMeasureCode]=S.[WeightUnitMeasureCode],R.[Weight]=S.[Weight],R.[DaysToManufacture]=S.[DaysToManufacture],R.[ProductLine]=S.[ProductLine],R.[Class]=S.[Class],R.[Style]=S.[Style],R.[ProductSubcategoryID]=S.[ProductSubcategoryID],R.[ProductModelID]=S.[ProductModelID],R.[SellStartDate]=S.[SellStartDate],R.[SellEndDate]=S.[SellEndDate],R.[DiscontinuedDate]=S.[DiscontinuedDate],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[Product] R JOIN #CT_Product C ON R.[ProductID]=C.[ProductID] JOIN ssis_flow.Delta_Product S ON S.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[Product]([ProductID],[Name],[ProductNumber],[MakeFlag],[FinishedGoodsFlag],[Color],[SafetyStockLevel],[ReorderPoint],[StandardCost],[ListPrice],[Size],[SizeUnitMeasureCode],[WeightUnitMeasureCode],[Weight],[DaysToManufacture],[ProductLine],[Class],[Style],[ProductSubcategoryID],[ProductModelID],[SellStartDate],[SellEndDate],[DiscontinuedDate],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[Name],S.[ProductNumber],S.[MakeFlag],S.[FinishedGoodsFlag],S.[Color],S.[SafetyStockLevel],S.[ReorderPoint],S.[StandardCost],S.[ListPrice],S.[Size],S.[SizeUnitMeasureCode],S.[WeightUnitMeasureCode],S.[Weight],S.[DaysToManufacture],S.[ProductLine],S.[Class],S.[Style],S.[ProductSubcategoryID],S.[ProductModelID],S.[SellStartDate],S.[SellEndDate],S.[DiscontinuedDate],S.[rowguid],S.[ModifiedDate],@B FROM #CT_Product C JOIN ssis_flow.Delta_Product S ON S.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[Product] R WHERE R.[ProductID]=S.[ProductID]);
INSERT stg.[Product]([ProductID],[Name],[ProductNumber],[MakeFlag],[FinishedGoodsFlag],[Color],[SafetyStockLevel],[ReorderPoint],[StandardCost],[ListPrice],[Size],[SizeUnitMeasureCode],[WeightUnitMeasureCode],[Weight],[DaysToManufacture],[ProductLine],[Class],[Style],[ProductSubcategoryID],[ProductModelID],[SellStartDate],[SellEndDate],[DiscontinuedDate],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[ProductID],R.[Name],R.[ProductNumber],R.[MakeFlag],R.[FinishedGoodsFlag],R.[Color],R.[SafetyStockLevel],R.[ReorderPoint],R.[StandardCost],R.[ListPrice],R.[Size],R.[SizeUnitMeasureCode],R.[WeightUnitMeasureCode],R.[Weight],R.[DaysToManufacture],R.[ProductLine],R.[Class],R.[Style],R.[ProductSubcategoryID],R.[ProductModelID],R.[SellStartDate],R.[SellEndDate],R.[DiscontinuedDate],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[Product] R JOIN #CT_Product C ON R.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;